<script setup lang="ts">
import { onBeforeUnmount, ref } from 'vue'
import { useRouter } from 'vue-router'
import ToolboxPage from '../ToolboxPage.vue'
import SvgIcon from '../components/SvgIcon.vue'
type BatchImage = { id: string; file: File; status: 'waiting' | 'compressing' | 'ready' | 'failed'; resultSize?: number; error?: string; outputName?: string }
const router = useRouter(); const imageInput = ref<HTMLInputElement>(); const imageBatchInput = ref<HTMLInputElement>(); const imageFolderInput = ref<HTMLInputElement>(); const imagePreviewUrl = ref(''); const imageFile = ref<File>(); const imageInfo = ref<{ width: number; height: number }>(); const imageMessage = ref('选择一张本地图片后，可预览并导出 PNG 或 JPEG。'); const imageOutputType = ref<'original' | 'image/png' | 'image/jpeg' | 'image/webp' | 'image/svg+xml'>('original'); const imageQuality = ref(82); const imageScale = ref(100); const compressedImage = ref<{ url: string; blob: Blob; format: string }>(); const imageCompressing = ref(false); const imageBatch = ref<BatchImage[]>([]); const imageBatchMessage = ref('可选择多张图片或一个图片文件夹，压缩后将统一导出到新文件夹。'); const maxImageFileSize = 100 * 1024 * 1024; const maxImagePixels = 12_000_000; let imageLoadRequest = 0
const backToPortal = () => router.push({ name: 'portal' }); const openImagePicker = () => imageInput.value?.click(); const supportedImageTypes = new Set(['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/bmp', 'image/svg+xml']); const isSupportedImageFile = (file: File) => supportedImageTypes.has(file.type.toLowerCase()) || /\.(png|jpe?g|webp|gif|bmp|svg)$/i.test(file.name)
const formatBytes = (bytes: number) => !Number.isFinite(bytes) || bytes < 0 ? '—' : bytes < 1024 ? `${bytes} B` : bytes < 1024 ** 2 ? `${(bytes / 1024).toFixed(1)} KB` : bytes < 1024 ** 3 ? `${(bytes / 1024 ** 2).toFixed(2)} MB` : `${(bytes / 1024 ** 3).toFixed(2)} GB`
const clearCompressedImage = () => { if (compressedImage.value?.url) URL.revokeObjectURL(compressedImage.value.url); compressedImage.value = undefined }
const invalidateImageOutputs = () => { clearCompressedImage(); imageBatch.value = imageBatch.value.map((item) => ({ ...item, status: 'waiting', resultSize: undefined, error: undefined, outputName: undefined })) }
const imageExtension = (format: string) => format === 'image/jpeg' ? 'jpg' : format === 'image/svg+xml' ? 'svg' : format.split('/')[1]
const resolveOutputFormat = (file?: File) => imageOutputType.value !== 'original' ? imageOutputType.value : file?.type === 'image/jpeg' || file?.type === 'image/png' || file?.type === 'image/webp' || file?.type === 'image/svg+xml' ? file.type : 'image/png'
const loadCanvasImage = (url: string): Promise<HTMLImageElement> => new Promise((resolve, reject) => { const image = new Image(); image.onload = () => resolve(image); image.onerror = () => reject(new Error('图片加载失败')); image.src = url })
const scaleCanvas = (canvas: HTMLCanvasElement) => { const scale = Number.isFinite(imageScale.value) ? Math.max(10, Math.min(100, imageScale.value)) : 100; if (scale >= 100) return canvas; const scaled = document.createElement('canvas'); scaled.width = Math.max(1, Math.round(canvas.width * scale / 100)); scaled.height = Math.max(1, Math.round(canvas.height * scale / 100)); const context = scaled.getContext('2d'); if (!context) throw new Error('无法缩放图片'); context.drawImage(canvas, 0, 0, scaled.width, scaled.height); return scaled }
const renderFileCanvas = async (file: File) => { const url = URL.createObjectURL(file); try { const image = await loadCanvasImage(url); if (!image.naturalWidth || !image.naturalHeight || image.naturalWidth * image.naturalHeight > maxImagePixels) throw new Error('图片超过 1200 万像素限制'); const canvas = document.createElement('canvas'); canvas.width = image.naturalWidth; canvas.height = image.naturalHeight; const context = canvas.getContext('2d'); if (!context) throw new Error('无法创建图片画布'); context.drawImage(image, 0, 0); return scaleCanvas(canvas) } finally { URL.revokeObjectURL(url) } }
const encodeCanvas = (canvas: HTMLCanvasElement, format = resolveOutputFormat(imageFile.value)) => new Promise<Blob>((resolve, reject) => { if (format === 'image/svg+xml') { const png = canvas.toDataURL('image/png'); resolve(new Blob([`<svg xmlns="http://www.w3.org/2000/svg" width="${canvas.width}" height="${canvas.height}" viewBox="0 0 ${canvas.width} ${canvas.height}"><image href="${png}" width="100%" height="100%"/></svg>`], { type: 'image/svg+xml' })); return } canvas.toBlob((blob) => blob ? resolve(blob) : reject(new Error('图片编码失败，请更换格式后重试。')), format, format === 'image/png' ? undefined : imageQuality.value / 100) })
const loadImage = (file?: File) => { const request = ++imageLoadRequest; if (!file || !isSupportedImageFile(file)) { imageMessage.value = '请选择 PNG、JPEG、WebP、GIF、BMP 或 SVG 图片文件。'; return } if (file.size > maxImageFileSize) { imageMessage.value = '单张图片不能超过 100 MB。'; return } if (imagePreviewUrl.value.startsWith('blob:')) URL.revokeObjectURL(imagePreviewUrl.value); clearCompressedImage(); imageFile.value = file; imagePreviewUrl.value = URL.createObjectURL(file); const image = new Image(); image.onload = () => { if (request !== imageLoadRequest) return; if (!image.naturalWidth || !image.naturalHeight || image.naturalWidth * image.naturalHeight > maxImagePixels) { imageMessage.value = '图片像素过大，请使用不超过 1200 万像素的图片。'; imageFile.value = undefined; imageInfo.value = undefined; return } imageInfo.value = { width: image.naturalWidth, height: image.naturalHeight }; imageMessage.value = '图片已加载，所有处理仅在本机完成。' }; image.onerror = () => { if (request !== imageLoadRequest) return; imageFile.value = undefined; imageInfo.value = undefined; imageMessage.value = '图片无法加载。请确认文件未损坏，并使用 PNG、JPG、WebP、GIF、BMP 或 SVG 格式。' }; image.src = imagePreviewUrl.value }
const loadImageBatch = (files: FileList | File[]) => { const candidates = Array.from(files); const images = candidates.filter((file) => isSupportedImageFile(file) && file.size <= maxImageFileSize).slice(0, 500); if (!images.length) { imageBatchMessage.value = '没有识别到可处理的图片文件。'; return } imageBatch.value = images.map((file, index) => ({ id: `${file.name}-${file.lastModified}-${index}`, file, status: 'waiting' })); loadImage(images[0]); const skipped = candidates.length - images.length; imageBatchMessage.value = `已加入 ${images.length} 张图片。${skipped ? `已跳过 ${skipped} 个非图片、超过 100 MB 或超出 500 张限制的文件。` : '可调整格式和质量后批量压缩。'}` }
const onImageSelected = (event: Event) => { const input = event.target as HTMLInputElement; loadImage(input.files?.[0]); input.value = '' }; const onImageBatchSelected = (event: Event) => { const input = event.target as HTMLInputElement; if (input.files) loadImageBatch(input.files); input.value = '' }; const onImageFolderSelected = onImageBatchSelected; const onImageDropped = (event: DragEvent) => { const files = event.dataTransfer?.files; if (!files?.length) return; if (files.length > 1) loadImageBatch(files); else loadImage(files[0]) }
const englishOutputName = (file: File, index: number) => { const sourceStem = file.name.replace(/\.[^.]+$/, ''); const asciiStem = sourceStem.normalize('NFKD').replace(/[^\x20-\x7E]/g, '').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '').toLowerCase(); return `${/[^\x00-\x7F]/.test(sourceStem) || !asciiStem ? 'image' : asciiStem}-${String(index + 1).padStart(3, '0')}.${imageExtension(resolveOutputFormat(file))}` }
const setBatchItem = (id: string, update: Partial<BatchImage>) => { imageBatch.value = imageBatch.value.map((item) => item.id === id ? { ...item, ...update } : item) }
const compressBatch = async () => { if (!imageBatch.value.length) { imageBatchMessage.value = '请先选择多张图片或一个图片文件夹。'; return } const outputDirectory = await window.developerTools.selectImageOutputDirectory(); if (!outputDirectory) return; imageCompressing.value = true; const outputFiles: Array<{ name: string; data: ArrayBuffer }> = []; let totalOutputBytes = 0; try { for (const [index, item] of imageBatch.value.entries()) { setBatchItem(item.id, { status: 'compressing', error: undefined }); try { const blob = await encodeCanvas(await renderFileCanvas(item.file), resolveOutputFormat(item.file)); const outputName = englishOutputName(item.file, index); totalOutputBytes += blob.size; if (totalOutputBytes > 512 * 1024 * 1024) throw new Error('批量输出超过 512 MB 上限'); outputFiles.push({ name: outputName, data: await blob.arrayBuffer() }); setBatchItem(item.id, { status: 'ready', resultSize: blob.size, outputName }) } catch (error) { setBatchItem(item.id, { status: 'failed', error: error instanceof Error ? error.message : String(error) }) } } if (!outputFiles.length) throw new Error('没有图片成功压缩，未创建导出文件夹。'); const result = await window.developerTools.saveCompressedImages(outputDirectory, outputFiles); const failures = imageBatch.value.filter((item) => item.status === 'failed').length; imageBatchMessage.value = `已导出 ${result.files.length} 张图片至：${result.directory}${failures ? `；${failures} 张处理失败。` : '。'}` } catch (error) { imageBatchMessage.value = error instanceof Error ? error.message : String(error) } finally { imageCompressing.value = false } }
const compressImage = async () => { if (!imageFile.value) return; imageCompressing.value = true; try { clearCompressedImage(); const format = resolveOutputFormat(imageFile.value); const blob = await encodeCanvas(await renderFileCanvas(imageFile.value), format); compressedImage.value = { url: URL.createObjectURL(blob), blob, format }; const change = Math.round((1 - blob.size / imageFile.value.size) * 100); imageMessage.value = change >= 0 ? `压缩完成，节省 ${change}% 空间。` : '已完成重新编码；当前设置的输出文件比原图更大，可降低质量或改用 WebP。' } catch (error) { imageMessage.value = error instanceof Error ? error.message : String(error) } finally { imageCompressing.value = false } }
const downloadCompressedImage = () => { if (!compressedImage.value) return; const extension = imageExtension(compressedImage.value.format); const link = document.createElement('a'); link.href = compressedImage.value.url; link.download = `${imageFile.value?.name.replace(/\.[^.]+$/, '') ?? 'image'}-tinied.${extension}`; link.click(); imageMessage.value = `已下载压缩后的 ${extension.toUpperCase()} 图片。` }
onBeforeUnmount(() => { if (imagePreviewUrl.value.startsWith('blob:')) URL.revokeObjectURL(imagePreviewUrl.value); clearCompressedImage() })
</script>
<template><ToolboxPage><header class="toolbox-heading"><div><p>设计工具 / LOCAL IMAGE</p><h2>本地图片压缩</h2><span>批量压缩、转换格式并导出至新文件夹；图片始终留在本机。</span></div><button class="back-button" @click="backToPortal">‹ 返回工具列表</button></header><input ref="imageInput" class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/bmp,image/svg+xml" @change="onImageSelected"><input ref="imageBatchInput" class="visually-hidden" type="file" multiple accept="image/png,image/jpeg,image/webp,image/gif,image/bmp,image/svg+xml" @change="onImageBatchSelected"><input ref="imageFolderInput" class="visually-hidden" type="file" webkitdirectory directory multiple accept="image/png,image/jpeg,image/webp,image/gif,image/bmp,image/svg+xml" @change="onImageFolderSelected"><section class="batch-import-card"><div><small>BATCH COMPRESS</small><strong>批量压缩并导出文件夹</strong><span>中文文件名会自动改为英文安全名，例如 <code>image-001.webp</code>。</span></div><button type="button" @click="imageBatchInput?.click()">选择多张图片</button><button class="primary" type="button" @click="imageFolderInput?.click()">选择图片文件夹</button></section><section class="image-dropzone" :class="{ 'has-image': imagePreviewUrl }" @click="openImagePicker" @dragover.prevent @drop.prevent="onImageDropped"><img v-if="imagePreviewUrl" :src="imagePreviewUrl" :alt="imageFile?.name ?? '图片预览'"><div v-else><SvgIcon name="image" /><strong>拖入图片开始压缩</strong><span>支持 PNG、JPEG、WebP、GIF、BMP 与 SVG · GIF 仅处理首帧</span></div></section><p class="tool-message">{{ imageMessage }}</p><section v-if="imageFile && imageInfo" class="image-details"><div><small>文件名称</small><strong>{{ imageFile.name }}</strong></div><div><small>像素尺寸</small><strong>{{ imageInfo.width }} × {{ imageInfo.height }}</strong></div><div><small>文件大小</small><strong>{{ formatBytes(imageFile.size) }}</strong></div></section><section v-if="imageFile && imageInfo" class="image-workbench"><div><h3>压缩与格式</h3><p>批量导出会统一使用以下参数。降低质量或尺寸比例可显著减小体积；SVG 为嵌入图片，并非矢量化。</p><label>格式 <select v-model="imageOutputType" @change="invalidateImageOutputs"><option value="original">尽量保持（GIF/BMP 转 PNG）</option><option value="image/png">统一 PNG</option><option value="image/jpeg">统一 JPG</option><option value="image/webp">统一 WebP（推荐）</option><option value="image/svg+xml">统一 SVG（嵌入图片）</option></select></label><label>清晰度（JPG/WebP） <input v-model.number="imageQuality" type="range" min="20" max="100" :disabled="imageOutputType === 'image/png' || imageOutputType === 'image/svg+xml'" @input="invalidateImageOutputs"><output>{{ imageQuality }}%</output></label><label>尺寸比例 <input v-model.number="imageScale" type="range" min="10" max="100" step="5" @input="invalidateImageOutputs"><output>{{ imageScale }}%</output></label><button class="primary" :disabled="imageCompressing" @click="compressImage">{{ imageCompressing ? '压缩中…' : '开始压缩' }}</button></div></section><section v-if="imageBatch.length" class="batch-queue"><header><div><small>待处理队列</small><strong>{{ imageBatch.length }} 张图片</strong></div><button class="primary" :disabled="imageCompressing" @click="compressBatch">{{ imageCompressing ? '正在批量压缩…' : '压缩并导出文件夹' }}</button></header><p class="tool-message">{{ imageBatchMessage }}</p><div class="batch-file-list"><div v-for="item in imageBatch" :key="item.id"><span :title="item.file.name">{{ item.file.name }}</span><small>{{ formatBytes(item.file.size) }}</small><strong :class="`batch-${item.status}`">{{ item.status === 'waiting' ? '等待处理' : item.status === 'compressing' ? '压缩中…' : item.status === 'ready' ? `${formatBytes(item.resultSize ?? 0)} · ${item.outputName}` : item.error ?? '处理失败' }}</strong></div></div></section><section v-if="compressedImage && imageFile" class="compression-result"><div><small>原始文件</small><strong>{{ formatBytes(imageFile.size) }}</strong></div><i aria-hidden="true">→</i><div><small>压缩结果</small><strong>{{ formatBytes(compressedImage.blob.size) }}</strong></div><div><small>空间变化</small><strong :class="{ 'file-larger': compressedImage.blob.size > imageFile.size }">{{ compressedImage.blob.size <= imageFile.size ? `节省 ${Math.round((1 - compressedImage.blob.size / imageFile.size) * 100)}%` : `增加 ${Math.round((compressedImage.blob.size / imageFile.size - 1) * 100)}%` }}</strong></div><button class="primary" @click="downloadCompressedImage">下载图片</button></section></ToolboxPage></template>
